[metadata] {"type": "create", "filePath": "/workspace/repo/crates/biome_css_analyze/src/lint/nursery/no_unknown_unit.rs", "content": "use biome_analyze::{context::RuleContext, declare_rule, Ast, Rule, RuleDiagnostic, RuleSource};
use biome_console::markup;
use biome_css_syntax::{
    AnyCssDimension, CssFunction, CssGenericProperty, CssQueryFeaturePlain, CssSyntaxKind,
};
use biome_rowan::{AstNode, SyntaxNodeCast, TextRange};

declare_rule! {
    /// Disallow unknown CSS units.
    ///
    /// For details on known CSS units, see the [MDN web docs](https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths).
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: 10pixels;
    /// }
    /// ```
    ///
    /// ```css,expect_diagnostic
    /// a {
    ///   width: calc(10px + 10pixels);
    /// }
    /// ```
    ///
    /// ### Valid
    ///
    /// ```css
    /// a {
    ///   width: 10px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10Px;
    /// }
    /// ```
    ///
    /// ```css
    /// a {
    ///   width: 10px;
    /// }
    /// ```
    ///
    pub NoUnknownUnit {
        version: "next",
        name: "noUnknownUnit",
        recommended: true,
        sources: &[RuleSource::Stylelint("unit-no-unknown")],
    }
}

const RESOLUTION_MEDIA_FEATURE_NAMES: [&str; 3] =
    ["resolution", "min-resolution", "max-resolution"];

pub struct NoUnknownUnitState {
    unit: String,
    span: TextRange,
}

impl Rule for NoUnknownUnit {
    type Query = Ast<AnyCssDimension>;
    type State = NoUnknownUnitState;
    type Signals = Option<Self::State>;
    type Options = ();

    fn run(ctx: &RuleContext<Self>) -> Option<Self::State> {
        let node = ctx.query();

        match node {
            AnyCssDimension::CssUnknownDimension(dimension) => {
                let unit_token = dimension.unit_token().ok()?;

                Some(NoUnknownUnitState {
                    unit: unit_token.text_trimmed().to_string(),
                    span: unit_token.text_trimmed_range(),
                })
            }
            AnyCssDimension::CssRegularDimension(dimension) => {
                let unit_token = dimension.unit_token().ok()?;
                let unit = unit_token.text_trimmed();

                // `x` is parsed as a valid unit because it's a resolution unit.
                // However, it's only valid in certain contexts, so we need to
                // check whether the surrounding context is a resolution one.
                // If it's not, the `x` is most likely a typo for `px`.
                if unit.eq_ignore_ascii_case("x") {
                    let mut allow_x = false;

                    for ancestor in unit_token.ancestors() {
                        match ancestor.kind() {
                            CssSyntaxKind::CSS_FUNCTION => {
                                let function = ancestor.cast::<CssFunction>()?;
                                let name = function.name().ok()?.value_token().ok()?;

                                if name.text_trimmed().to_lowercase().ends_with("image-set") {
                                    allow_x = true;
                                }

                                break;
                            }
                            CssSyntaxKind::CSS_GENERIC_PROPERTY => {
                                let property = ancestor.cast::<CssGenericProperty>()?;
                                let name = property
                                    .name()
                                    .ok()?
                                    .as_css_identifier()?
                                    .value_token()
                                    .ok()?;

                                if name.text_trimmed().to_lowercase() == "image-resolution" {
                                    allow_x = true;
                                }

                                break;
                            }
                            CssSyntaxKind::CSS_QUERY_FEATURE_PLAIN => {
                                let query = ancestor.cast::<CssQueryFeaturePlain>()?;
                                let name = query.name().ok()?.value_token().ok()?;

                                if RESOLUTION_MEDIA_FEATURE_NAMES
                                    .contains(&name.text_trimmed().to_lowercase().as_str())
                                {
                                    allow_x = true;
                                }

                                break;
                            }
                            _ => {}
                        }
                    }

                    if !allow_x {
                        return Some(NoUnknownUnitState {
                            unit: unit.to_string(),
                            span: unit_token.text_trimmed_range(),
                        });
                    }
                }

                None
            }
            _ => None,
        }
    }

    fn diagnostic(_: &RuleContext<Self>, state: &Self::State) -> Option<RuleDiagnostic> {
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                state.span,
                markup! {
                    "Unexpected unknown unit: "<Emphasis>{state.unit}</Emphasis>
                },
            )
            .note(markup! {
                "See "<Hyperlink href="https://developer.mozilla.org/en-US/docs/Learn/CSS/Building_blocks/Values_and_units#lengths">"MDN web docs"</Hyperlink>" for more details."
            })
            .footer_list(
                markup! {
                    "Use a known unit instead, such as:"
                },
                &["px", "em", "rem", "etc."],
            ),
        )
    }
}
